{"content":"<!-- AUTO-GENERATED PORTFOLIO — Hermes Work Aggregator -->
<!DOCTYPE html>
<html lang="ru">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Hermes Work Portfolio — All Projects</title>
<style>
:root{
  --bg:#0d0d12;--surface:#16161d;--border:#2a2a3a;--text:#e8e8ee;--muted:#88889a;
  --accent:#6c5ce7;--accent-hover:#8b7cff;--accent-bg:#1e1a3a;--card-hover:#3a3670;
  --cat-border:#3a3670;--tag-muted:#555;--footer-border:#2a2a3a;--empty:#555;
  --nav-btn-bg:#1e1e2a;--nav-btn:#aaa}
[data-theme=light]{
  --bg:#f7f7f8;--surface:#fff;--border:#eaeaea;--text:#1a1a1a;--muted:#888;
  --accent:#6c5ce7;--accent-hover:#5a4bd1;--accent-bg:#f0edff;--card-hover:#d4ccff;
  --cat-border:#eeeef0;--tag-muted:#bbb;--footer-border:#eaeaea;--empty:#aaa;
  --nav-btn-bg:#f0f0f2;--nav-btn:#555}
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{font-family:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;background:var(--bg);color:var(--text);transition:background .2s,color .2s;min-height:100vh}
img{max-width:100%;height:auto;display:block}
a{color:inherit;text-decoration:none}
button{cursor:pointer;border:none;background:none;font:inherit}

/* HEADER */
header{background:var(--surface);border-bottom:1px solid var(--border);position:sticky;top:0;z-index:100;backdrop-filter:blur(12px);background:rgba(22,22,29,.9)}
[data-theme=light] header{background:rgba(255,255,255,.9)}
.header-inner{max-width:1400px;margin:0 auto;padding:14px 24px;display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}
.logo{font-weight:800;font-size:20px;letter-spacing:-.5px;text-decoration:none;color:var(--text)}
.logo span{color:var(--muted);font-weight:400}
.logo em{font-style:normal;color:var(--accent)}
.header-right{display:flex;align-items:center;gap:8px}
.lang-btn,.theme-btn{padding:6px 10px;border:1px solid var(--border);border-radius:6px;background:var(--nav-btn-bg);color:var(--nav-btn);font-size:12px;font-weight:600;transition:all .15s;font-family:inherit;line-height:1}
.lang-btn:hover,.theme-btn:hover{border-color:var(--accent);color:var(--accent)}
.lang-btn.active{background:var(--accent);border-color:var(--accent);color:#fff}
.lang-btn{min-width:32px;text-align:center;text-transform:uppercase}
.theme-btn{font-size:16px;padding:6px 8px;line-height:1}

/* HERO */
.hero{max-width:1400px;margin:0 auto;padding:40px 24px 0}
.hero-top{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px;margin-bottom:4px}
.hero h1{font-size:32px;font-weight:800;letter-spacing:-1px}
.hero .sub{font-size:15px;color:var(--muted);line-height:1.5;max-width:600px}
.hero-meta{font-size:14px;color:var(--muted)}
.hero-cta{display:flex;gap:8px;margin-top:20px;flex-wrap:wrap}
.btn-primary{padding:12px 28px;background:var(--accent);color:#fff;border-radius:8px;font-weight:600;text-decoration:none;font-size:15px;transition:background .15s}
.btn-primary:hover{background:var(--accent-hover)}
.btn-secondary{padding:12px 28px;background:var(--cat-hover);color:var(--text);border-radius:8px;font-weight:500;text-decoration:none;font-size:15px;transition:background .15s}
.btn-secondary:hover{background:var(--card-hover)}

/* LAYOUT */
.layout{max-width:1400px;margin:0 auto;padding:24px;display:grid;grid-template-columns:220px 1fr;gap:28px}

/* SIDEBAR */
.sidebar{position:sticky;top:85px;align-self:start}
.sidebar h3{font-size:11px;text-transform:uppercase;letter-spacing:1px;color:var(--muted);margin-bottom:12px;font-weight:600}
.cat-list{list-style:none}
.cat-list li{margin-bottom:2px}
.cat-list a{display:block;padding:8px 12px;border-radius:8px;font-size:14px;font-weight:500;color:var(--muted);text-decoration:none;transition:all .15s}
.cat-list a:hover{background:var(--cat-hover);color:var(--text)}
.cat-list a.active{background:var(--accent);color:#fff;font-weight:600}
.cat-list .count{float:right;color:var(--tag-muted);font-size:12px;font-weight:400}
.cat-list a.active .count{color:rgba(255,255,255,.5)}

/* MAIN */
.main{min-height:50vh}
.section-title{display:none;align-items:baseline;justify-content:space-between;margin-bottom:16px}
.section-title.show{display:flex}
.section-title h2{font-size:18px;font-weight:700}
.section-title .all-link{font-size:13px;color:var(--accent);text-decoration:none;font-weight:500}
.section-title .all-link:hover{text-decoration:underline}

/* PROJECT GRID */
.project-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:16px;margin-bottom:40px}
.project-card{background:var(--surface);border-radius:12px;overflow:hidden;border:1px solid var(--border);transition:all .2s;text-decoration:none;color:inherit;display:block}
.project-card:hover{border-color:var(--card-hover);box-shadow:0 4px 20px rgba(108,92,231,.08);transform:translateY(-2px)}
.project-card .thumb{width:100%;height:170px;object-fit:cover;display:block;background:var(--cat-hover)}
.project-card .info{padding:14px 16px 16px}
.project-card .cat-tag{display:inline-block;font-size:11px;font-weight:600;color:var(--accent);background:var(--accent-bg);padding:2px 8px;border-radius:100px;margin-bottom:6px}
.project-card h3{font-size:15px;font-weight:600;margin-bottom:4px;line-height:1.3}
.project-card .desc{font-size:13px;color:var(--muted);line-height:1.5;margin-bottom:8px}
.project-card .meta{font-size:12px;color:var(--tag-muted);margin-bottom:10px}
.project-card .btn{display:inline-flex;align-items:center;gap:4px;padding:6px 14px;background:var(--accent);color:#fff;border-radius:6px;font-size:12px;font-weight:600;text-decoration:none;transition:background .15s}
.project-card .btn:hover{background:var(--accent-hover)}

/* EMPTY */
.empty-state{text-align:center;padding:60px 20px;color:var(--empty);font-size:14px;display:none}
.empty-state.show{display:block}

/* FOOTER */
footer{max-width:1400px;margin:0 auto;padding:32px 24px;border-top:1px solid var(--footer-border);color:var(--tag-muted);font-size:13px;text-align:center}

/* RESPONSIVE */
@media(max-width:768px){
  .layout{grid-template-columns:1fr;padding:16px}
  .sidebar{position:static;margin-bottom:4px}
  .sidebar h3{display:none}
  .cat-list{display:flex;gap:4px;overflow-x:auto;padding-bottom:8px;flex-wrap:nowrap}
  .cat-list li{flex-shrink:0}
  .cat-list a{padding:6px 14px;font-size:13px;white-space:nowrap}
  .project-grid{grid-template-columns:1fr}
  .hero h1{font-size:24px}
  .hero .sub{font-size:14px}
  .header-inner{flex-wrap:wrap}
}
</style>
</head>
<body>

<header>
<div class="header-inner">
<a href="./" class="logo">Hermes <span>//</span> <em>Portfolio</em></a>
<div class="header-right">
<button class="lang-btn active" data-lang="ru">RU</button>
<button class="lang-btn" data-lang="en">EN</button>
<button class="theme-btn" id="themeToggle" title="Toggle theme">🌙</button>
</div>
</div>
</header>

<section class="hero">
<div class="hero-top">
<h1 data-i18n="title">Hermes Portfolio</h1>
<span class="hero-meta" data-i18n="subtitle">70+ проектов · AI · CPA · Web · Automation</span>
</div>
<p class="sub" data-i18n="description">Все работы в одном месте: бизнес-сайты, CPA лендинги, арбитражные схемы, AI-инструменты, Telegram-боты, эксперименты. Открывай файл локально — всё работает без сервера.</p>
<div class="hero-cta">
<a href="#projects" class="btn-primary" data-i18n="view_projects">⟶ Посмотреть работы</a>
<a href="#stats" class="btn-secondary" data-i18n="stats">Статистика</a>
</div>
</section>

<div class="layout">
<aside class="sidebar">
<h3 data-i18n="categories">Категории</h3>
<ul class="cat-list" id="catList"></ul>
</aside>

<main class="main" id="projects"></main>
</div>

<section id="stats" style="max-width:1400px;margin:0 auto;padding:40px 24px;border-top:1px solid var(--border);text-align:center">
<h2 style="font-size:24px;font-weight:800;margin-bottom:8px;letter-spacing:-.5px" data-i18n="stats_title">По цифрам</h2>
