let currentLang = 'ru';
let currentCat = 'all';
let theme = localStorage.getItem('theme') || 'light';

document.documentElement.setAttribute('data-theme',theme);
document.getElementById('themeToggle').textContent = theme === 'dark' ? '☀️' : '🌙';
document.getElementById('themeToggle').addEventListener('click',()=>{
theme = theme === 'dark' ? 'light' : 'dark';
document.documentElement.setAttribute('data-theme',theme);
localStorage.setItem('theme',theme);
document.getElementById('themeToggle').textContent = theme === 'dark' ? '☀️' : '🌙';
});

function translate(lang){
currentLang = lang;
document.querySelectorAll('[data-i18n]').forEach(el=>{
const key = el.dataset.i18n;
if(LANG[lang][key]) el.textContent = LANG[lang][key];
});
document.querySelectorAll('.lang-btn').forEach(b=>b.classList.toggle('active',b.dataset.lang===lang));
renderProjects();
}

function renderProjects(){
const main = document.getElementById('projects');
const filtered = currentCat === 'all' ? PROJECTS : PROJECTS.filter(p=>p.cat===currentCat);
if(!filtered.length){
main.innerHTML = `<div class="empty-state show">${LANG[currentLang].empty}</div>`;
return;
}
const groups = {};
filtered.forEach(p=>{
if(!groups[p.cat]) groups[p.cat] = [];
groups[p.cat].push(p);
});
let html = '';
for(const[cat,items] of Object.entries(groups)){
const catMeta = CAT_META[cat] || {label:{ru:cat,en:cat},color:'#666',icon:'📦'};
const catName = catMeta.label[currentLang] || cat;
html += `<section class="project-section" data-cat="${cat}">`;
html += `<div class="section-title show"><h2>${catMeta.icon} ${catName}</h2></div>`;
html += `<div class="project-grid">`;
items.forEach(p=>{
html += `<a href="${p.url}" class="project-card" target="_blank">`;
html += `<img class="thumb" src="${p.img}" alt="" loading="lazy">`;
html += `<div class="info">`;
html += `<span class="cat-tag">${catName}</span>`;
html += `<h3>${p.name[currentLang]}</h3>`;
html += `<p class="desc">${p.desc[currentLang]}</p>`;
html += `<div class="meta">${p.meta[currentLang]}</div>`;
html += `<span class="btn">↗ ${currentLang === 'en' ? 'Open' : 'Открыть'}</span>`;
html += `</div></a>`;
});
html += `</div></section>`;
}
main.innerHTML = html;
}

document.getElementById('catList').addEventListener('click',e=>{
const a = e.target.closest('a');
if(!a) return;
e.preventDefault();
document.querySelectorAll('.cat-list a').forEach(x=>x.classList.remove('active'));
a.classList.add('active');
currentCat = a.dataset.cat;
renderProjects();
});

document.querySelectorAll('.lang-btn').forEach(btn=>{
btn.addEventListener('click',()=>translate(btn.dataset.lang));
});

function buildCatList(){
const cats = [...new Set(PROJECTS.map(p=>p.cat))];
let html = `<li><a href="#" class="active" data-cat="all" data-i18n="all"><span data-i18n="all">Все проекты</span> <span class="count">${PROJECTS.length}</span></a></li>`;
cats.forEach(cat=>{
const meta = CAT_META[cat] || {label:{ru:cat,en:cat},icon:'📦'};
const count = PROJECTS.filter(p=>p.cat===cat).length;
const label = meta.label[currentLang] || cat;
html += `<li><a href="#" data-cat="${cat}"><span>${meta.icon} ${label}</span> <span class="count">${count}</span></a></li>`;
});
document.getElementById('catList').innerHTML = html;
updateStats();
}

function updateStats(){
const cats = new Set(PROJECTS.map(p=>p.cat));
document.getElementById('statProjects').textContent = PROJECTS.length;
document.getElementById('statCategories').textContent = cats.size;
document.getElementById('statFiles').textContent = PROJECTS.length;
document.getElementById('statTypes').textContent = cats.size;
}

translate('ru');
buildCatList();
</script>
</body>
