"""
Hermes Web Access Tools - lightweight wrapper around existing CLI tools.
Provides: YouTube search/transcript, web search/read, GitHub read, RSS fetch.
No external installation needed - uses yt-dlp, curl, python stdlib.
"""
import subprocess, json, sys, os
from pathlib import Path
from typing import List, Dict, Any, Optional

PROXY = "socks5://127.0.0.1:10806"

class HermesWebAccess:
    """Web access tools for Hermes autonomous research."""

    @staticmethod
    def youtube_search(query: str, max_results: int = 5) -> List[Dict[str, Any]]:
        """Search YouTube and return video metadata."""
        try:
            result = subprocess.run([
                "yt-dlp", "--proxy", PROXY,
                f"ytsearch{max_results}:{query}",
                "--print", "%(title)s|%(url)s|%(channel)s|%(view_count)s|%(duration)s|%(upload_date)s",
                "--flat-playlist"
            ], capture_output=True, text=True, timeout=60)

            videos = []
            for line in result.stdout.strip().split('\n'):
                if '|' in line and line.strip():
                    parts = line.split('|')
                    if len(parts) >= 4:
                        videos.append({
                            "title": parts[0],
                            "url": parts[1],
                            "channel": parts[2],
                            "views": int(parts[3]) if parts[3].isdigit() else 0,
                            "duration": parts[4] if len(parts) > 4 else "",
                            "upload_date": parts[5] if len(parts) > 5 else ""
                        })
            return videos
        except Exception as e:
            return [{"error": str(e)}]

    @staticmethod
    def youtube_transcript(url: str, langs: str = "en,ru") -> Dict[str, Any]:
        """Get YouTube video description and auto-generated subtitles."""
        try:
            # Get description
            desc_result = subprocess.run([
                "yt-dlp", "--proxy", PROXY, "--print", "description", url
            ], capture_output=True, text=True, timeout=60)

            # Get subtitles
            sub_result = subprocess.run([
                "yt-dlp", "--proxy", PROXY,
                "--write-auto-subs", "--sub-langs", langs,
                "--skip-download", "--convert-subs", "srt",
                "-o", "-", url
            ], capture_output=True, text=True, timeout=60)

            return {
                "description": desc_result.stdout.strip(),
                "subtitles": sub_result.stdout.strip() if sub_result.stdout else "",
                "error": desc_result.stderr if desc_result.returncode != 0 else None
            }
        except Exception as e:
            return {"error": str(e)}

    @staticmethod
    def web_search(query: str, max_results: int = 10) -> List[Dict[str, Any]]:
        """Search web via multiple backends."""
        results = []

        # Try Exa via mcporter if available
        try:
            result = subprocess.run([
                "mcporter", "call", "exa.web_search_exa",
                json.dumps({"query": query, "max_results": max_results})
            ], capture_output=True, text=True, timeout=30)
            if result.returncode == 0:
                data = json.loads(result.stdout)
                return data.get("results", [])
        except:
            pass

        # Fallback: DuckDuckGo HTML scrape
        try:
            import urllib.parse
            url = f"https://html.duckduckgo.com/html/?q={urllib.parse.quote(query)}"
            result = subprocess.run(["curl", "-s", "-A", "Mozilla/5.0", "--proxy", PROXY, url], 
                                  capture_output=True, text=True, timeout=30)
            # Simple parse
            from html.parser import HTMLParser
            class DDGParser(HTMLParser):
                def __init__(self):
                    super().__init__()
                    self.results = []
                    self.in_result = False
                    self.current = {}
            # Simplified - just return empty for now, rely on other methods
            return []
        except:
            return []

        return results

    @staticmethod
    def web_read(url: str) -> str:
        """Read webpage content via Jina AI reader (free, no API key)."""
        try:
            result = subprocess.run([
                "curl", "-s", "--max-time", "30",
                f"https://r.jina.ai/{url}"
            ], capture_output=True, text=True, timeout=35)
            return result.stdout
        except Exception as e:
            return f"Error: {e}"

    @staticmethod
    def github_read(repo: str, path: str = "") -> str:
        """Read file from GitHub raw."""
        url = f"https://raw.githubusercontent.com/{repo}/main/{path}"
        return HermesWebAccess.web_read(url)

    @staticmethod
    def rss_fetch(url: str) -> str:
        """Fetch RSS/Atom feed."""
        try:
            result = subprocess.run([
                "curl", "-s", "--max-time", "30", url
            ], capture_output=True, text=True, timeout=35)
            return result.stdout
        except Exception as e:
            return f"Error: {e}"

# CLI for direct usage
if __name__ == "__main__":
    import argparse
    parser = argparse.ArgumentParser(description="Hermes Web Access Tools")
    sub = parser.add_subparsers(dest="cmd", required=True)

    p = sub.add_parser("youtube-search")
    p.add_argument("query"); p.add_argument("--max", type=int, default=5)

    p = sub.add_parser("youtube-transcript")
    p.add_argument("url"); p.add_argument("--langs", default="en,ru")

    p = sub.add_parser("web-read")
    p.add_argument("url")

    p = sub.add_parser("github-read")
    p.add_argument("repo"); p.add_argument("--path", default="")

    p = sub.add_parser("rss-fetch")
    p.add_argument("url")

    args = parser.parse_args()
